  assert.equal(await run('document.querySelector(".research-library").textContent.includes("写作按相关性选用来源摘要；参考资料需要结合本书设定，不能直接当作小说事实。")'), false, 'the specified fixed research note is removed while sources and search remain usable')
  await run('document.querySelector(".research-library .ant-pagination-item-2").click()')
  await wait('document.querySelectorAll(".research-library__sources article").length===2')
  await edit('[aria-label="需要查找的创作资料"]', '适合本书的灯具资料')
  await click('搜索并保存参考')
  await wait('document.querySelector(".research-library").textContent.includes("新保存的隔离参考来源")')
  assert.equal(await run('window.calls.filter(c=>c.kind==="research.search").length'), 1)
  await run('document.querySelector(".ant-drawer-close").click()')
