  await click('开始这一轮')
  await wait('window.fixture.runs.length===1')
  await tab('候选与评审')
  await wait('document.querySelector(".candidate-review")?.textContent.includes("隔离候选的独立修订")')
  assert.equal(await run('window.fixture.entities[0].summary'), '未来人形的内部规划内容。', 'candidate creation leaves formal fixture content unchanged')
  await edit('#object-version-feedback', '保留拨灯芯的动作，补充她自主修灯的日常。')
  await click('继续修订原目标')
  await wait('document.querySelector("#object-task-request")?.value.includes("补充她自主修灯")')
  await click('开始这一轮')
  await wait('window.fixture.runs.length===2')
  assert.equal(await run('window.fixture.runs[1].sourceArtifactId'), await run('window.fixture.runs[0].artifactId'), 'revision keeps the selected candidate as its source')
  assert.equal(await run('window.fixture.runs[1].stage'), 'characters')
  await tab('候选与评审')
  await wait('!![...document.querySelectorAll("button")].find(el=>el.textContent.trim()==="应用这一版")')
  await click('应用这一版')
  await wait('window.calls.some(c=>c.kind==="candidate.apply") && document.querySelector(".candidate-review")?.textContent.includes("已写入正式内容")')
  assert.equal(await run('window.fixture.entities[0].summary'), '隔离候选的独立修订。')
  await run('document.querySelector(".object-task-drawer .ant-drawer-close").click()')
  await wait('!document.querySelector(".ant-drawer-body")')
  await click('世界规则', 'document.querySelector("nav[aria-label=\\"世界与人物分区\\"]")')
  await wait('!!document.querySelector("nav[aria-label=\\"世界规则主题\\"]")')
  await click('人物', 'document.querySelector("nav[aria-label=\\"世界与人物分区\\"]")')
  await wait('document.querySelector(".atlas-profile h2")?.textContent==="阿烛"')
  assert.equal(await run('document.querySelector("[aria-label=\\"查找人物\\"]").value'), '阿烛', 'return from rules preserves the person list filter')
  await click('形象日常')
  await snapshot('workspace-characters-1440.png')
  for (const width of [1280, 720]) {
    win.setContentSize(width, 1000)
    await pause(180)
    await noOverflow('characters ' + width)
    await snapshot('workspace-characters-' + width + '.png')
  }
  win.setContentSize(1440, 1000)
  await go('writing/editor?chapterId=682')
  await wait('!!document.querySelector("textarea[aria-label=\\"第 1 章正文\\"]")')
  assert.equal(await run('getComputedStyle(document.querySelector(".manuscript-sticky-header")).position'), 'sticky', 'chapter actions stay in the sticky workspace heading')
  const originalProse = await run('window.fixture.chapters[0].content')
  const dirtyProse = originalProse + '\n她扶住了旧铜灯。'
  await edit('textarea[aria-label="第 1 章正文"]', dirtyProse)
  await click('本章安排')
  await wait('!!document.querySelector(".author-arrangement") && document.querySelector("textarea[aria-label=\\"第 1 章正文\\"]")?.value.includes("她扶住了旧铜灯")')
  assert.equal(await run('window.fixture.chapters[0].content'), originalProse, 'opening chapter arrangement preserves unsaved prose without auto-saving')
  await run('{const section=[...document.querySelectorAll(".author-arrangement section")].find(el=>el.querySelector("h3")?.textContent==="完整大纲");section.querySelector("button").click()}')
  await wait('!!document.querySelector(".ant-modal textarea")')
  const unsavedArrangement = '未保存安排哨兵：只保留在当前编辑框，不写入章节。'
  const outlineBeforeGuard = await run('window.fixture.chapters[0].outline')
  progress('dirty arrangement committed, then native same-chapter navigation')
  // Observe the actual child dirty-state commit, then navigate immediately in
  // its MutationObserver microtask. No extra IPC/sleep may accidentally flush
  // the parent's old passive guard and mask the native-navigation race.
  await run(`{const button=[...document.querySelectorAll('.author-arrangement button')].find(el=>el.textContent.includes('让 AI 完善本章安排'));if(!button||button.disabled)throw Error('Arrangement action must start enabled');window.arrangementNavigation={fired:false};const observer=new MutationObserver(()=>{if(!button.disabled)return;observer.disconnect();window.arrangementNavigation={fired:true,childDirtyCommitted:button.disabled,aiActionDisabled:[...document.querySelectorAll('.manuscript-toolbar button')].some(el=>el.textContent.includes('AI')&&el.disabled),previousHash:location.hash};location.hash='/novels/292/writing/editor?chapterId=682'});observer.observe(button,{attributes:true,attributeFilter:['disabled']})}`)
  await edit('.ant-modal textarea', unsavedArrangement)
  await wait('window.arrangementNavigation?.fired')
  assert.equal(await run('window.arrangementNavigation.childDirtyCommitted'), true, 'native navigation starts from a real committed arrangement edit')
  await wait('!!document.querySelector(".ant-modal-confirm")')
  assert.equal(await run('document.querySelectorAll(".ant-modal-confirm").length'), 1, 'native same-chapter panel change raises one confirmation for a dirty arrangement')
  await click('继续编辑')
  await wait('!document.querySelector(".ant-modal-confirm")')
  assert.equal(await run('!!document.querySelector(".ant-modal textarea")'), true, 'cancel native same-chapter navigation keeps the arrangement editor mounted')
  assert.equal(await run('document.querySelector(".ant-modal textarea").value'), unsavedArrangement, 'cancel native panel navigation preserves the exact arrangement draft')
  assert.equal(await run('new URLSearchParams(location.hash.split("?")[1]).get("panel")'), 'arrangement', 'cancel restores the original chapter context panel')
  assert.equal(await run('document.querySelector("textarea[aria-label=\\"第 1 章正文\\"]").value'), dirtyProse, 'arrangement guard also keeps the prose draft')
  progress('cancel retained arrangement; discard internally once')
  await click('参考资料')
  await wait('!!document.querySelector(".ant-modal-confirm")')
  assert.equal(await run('document.querySelectorAll(".ant-modal-confirm").length'), 1, 'internal panel switch asks once before discarding the arrangement draft')
  await click('放弃并切换')
  await wait('!!document.querySelector("[aria-label=\\"本章人物与地点参考\\"]") && ![...document.querySelectorAll(".ant-modal")].some(el=>el.offsetParent)')
  await pause(250)
  assert.equal(await run('document.querySelectorAll(".ant-modal-confirm").length'), 0, 'explicit internal discard does not trigger a second global confirmation')
  assert.equal(await run('window.fixture.chapters[0].outline'), outlineBeforeGuard, 'discarded arrangement was never written to the chapter')
  await click('本章安排')
  await wait('!!document.querySelector(".author-arrangement")')
  await run('{const section=[...document.querySelectorAll(".author-arrangement section")].find(el=>el.querySelector("h3")?.textContent==="完整大纲");section.querySelector("button").click()}')
  await wait('!!document.querySelector(".ant-modal textarea")')
