      const config = await run('({width:innerWidth,controls:[...document.querySelectorAll(".author-window-controls button")].map(el=>{const r=el.getBoundingClientRect();return {label:el.getAttribute("aria-label"),left:r.left,right:r.right,top:r.top,bottom:r.bottom,width:r.width,appRegion:getComputedStyle(el).getPropertyValue("-webkit-app-region")}}),task:(()=>{const el=document.querySelector(".author-shell-header .task-indicator"),r=el?.getBoundingClientRect();return r?{left:r.left,right:r.right,appRegion:getComputedStyle(el).getPropertyValue("-webkit-app-region")}:null})()})')
